@Test
public void testGetActiveReservationWithRandomOrder() {
    final GroupComputeResourcePreference pref = new GroupComputeResourcePreference();
    final ComputeResourceReservation res1 = new ComputeResourceReservation("id1", "res1", Arrays.asList("cpu", "gpu"), System.currentTimeMillis() - 10000, System.currentTimeMillis() + 10000);
    // expired
    final ComputeResourceReservation res2 = new ComputeResourceReservation("id2", "res2", Arrays.asList("cpu", "gpu"), System.currentTimeMillis() - 20000, System.currentTimeMillis() - 10000);
    // future
    final ComputeResourceReservation res3 = new ComputeResourceReservation("id3", "res3", Arrays.asList("cpu", "gpu"), System.currentTimeMillis() + 10000, System.currentTimeMillis() + 20000);
    // wrong queue
    final ComputeResourceReservation res4 = new ComputeResourceReservation("id3", "res3", Arrays.asList("shared", "compute"), System.currentTimeMillis() + 10000, System.currentTimeMillis() + 20000);
    final List<ComputeResourceReservation> reservations = Arrays.asList(res1, res2, res3, res4);
    Collections.shuffle(reservations);
    //        pref.setReservations(reservations); FIXME
    final ComputeResourceReservation result = GroupComputeResourcePreferenceUtil.getActiveReservationForQueue(pref, "cpu");
    Assertions.assertSame(res1, result);
}

