    Assertions.assertTrue(entityId2SharedUsers.contains(user3) && entityId2SharedUsers.contains(user7), "user3 and user7 in shared users");
    Assertions.assertEquals(1, sharingRegistryServerHandler.getListOfDirectlySharedGroups(domainId, entityId3, permissionTypeId1).size());
    Assertions.assertEquals(groupId2, sharingRegistryServerHandler.getListOfDirectlySharedGroups(domainId, entityId3, permissionTypeId1).get(0).getGroupId());
    // Test that new users are added to initialUserGroupId
    UserGroup initialUserGroup = new UserGroup();
    String initialUserGroupName = "initial user group";
    String initialUserGroupId = domainId + ":" + initialUserGroupName;
    initialUserGroup.setGroupId(initialUserGroupId);
